/**
 * /admin/snap — OPE-1341 "Snap booth" capture page. ADMIN-only via the admin
 * layout. Installable on its own (`snap-manifest.json`, start_url + scope
 * `/admin/snap`) so it opens full-screen from the phone's home screen.
 * OPE-1552: its own icon set (`/icons/snap/*`, generated by
 * `scripts/generate-snap-icons.mjs`) and home-screen label "Snap", so it is
 * distinguishable from the main site's install. The root favicon is still
 * emitted — Next unshifts the static favicon after merging page `icons`.
 */
import { requireAdmin } from "@/lib/require-admin";
import type { Metadata, Viewport } from "next";
import { SnapCapture } from "./snap-capture";

export const metadata: Metadata = {
  title: "Snap booth",
  manifest: "/snap-manifest.json",
  robots: { index: false, follow: false },
  icons: { apple: [{ url: "/icons/snap/apple-touch-icon.png", sizes: "180x180" }] },
  appleWebApp: { capable: true, title: "Snap", statusBarStyle: "black-translucent" },
};

export const viewport: Viewport = {
  themeColor: "#111827",
  width: "device-width",
  initialScale: 1,
};

export default async function SnapPage() {
  await requireAdmin();
  return <SnapCapture />;
}
